//! What every backend computes the same way: the arithmetic of the
//! operations and the conversions to and from memory. The interpreter
//! calls these as it goes; code generated by the recompiler calls them
//! too, so that the two cannot differ in them.

use crate::fpu::{self, FMem};
use crate::interp::{Cpu, Fault};
use crate::memory::Memory;
use crate::sem::{Bin, Size, Un};

#[inline(always)]
pub fn bin(op: Bin, a: u32, b: u32) -> u32 {
    match op {
        Bin::Add => a.wrapping_add(b),
        Bin::Sub => a.wrapping_sub(b),
        Bin::And => a & b,
        Bin::Or => a | b,
        Bin::Xor => a ^ b,
        Bin::Shl => a.wrapping_shl(b),
        Bin::Shr => a.wrapping_shr(b),
        Bin::Sar => (a as i32).wrapping_shr(b) as u32,
        Bin::Mul => a.wrapping_mul(b),
        Bin::MulHighU => ((a as u64 * b as u64) >> 32) as u32,
        Bin::MulHighS => ((a as i32 as i64 * b as i32 as i64) >> 32) as u32,
        Bin::Eq => (a == b) as u32,
        Bin::Ne => (a != b) as u32,
        Bin::LtU => (a < b) as u32,
    }
}

#[inline(always)]
pub fn un(op: Un, a: u32) -> u32 {
    match op {
        Un::Not => !a,
        Un::Neg => a.wrapping_neg(),
        Un::SignExtend8 => a as i8 as u32,
        Un::SignExtend16 => a as i16 as u32,
        Un::ParityEven => ((a as u8).count_ones() + 1) & 1,
    }
}

/// Divides `high:low` by `divisor`, all `size` wide: the quotient and the
/// remainder, or `None` where the hardware faults (a zero divisor, a
/// quotient that does not fit).
pub fn divide(signed: bool, size: Size, high: u32, low: u32, divisor: u32) -> Option<(u32, u32)> {
    let bits = size.bits();
    let mask = size.mask() as u64;
    let dividend = (high as u64) << bits | low as u64;
    let (quotient, remainder) = if signed {
        let shift = 64 - 2 * bits;
        let dividend = ((dividend << shift) as i64) >> shift;
        let divisor = ((divisor as u64) << (64 - bits)) as i64 >> (64 - bits);
        let limit = 1i64 << (bits - 1);
        match (dividend.checked_div(divisor), dividend.checked_rem(divisor)) {
            (Some(quotient), Some(remainder)) if (-limit..limit).contains(&quotient) => {
                (quotient as u64 & mask, remainder as u64 & mask)
            }
            _ => return None,
        }
    } else {
        match (dividend.checked_div(divisor as u64), dividend.checked_rem(divisor as u64)) {
            (Some(quotient), Some(remainder)) if quotient <= mask => (quotient, remainder),
            _ => return None,
        }
    };
    Some((quotient as u32, remainder as u32))
}

/// `cpuid`: a Pentium II, the class of machine the game was written for.
pub fn cpuid(cpu: &mut Cpu) {
    let (eax, ebx, ecx, edx) = match cpu.regs[0] {
        0 => (1, u32::from_le_bytes(*b"Genu"), u32::from_le_bytes(*b"ntel"), u32::from_le_bytes(*b"ineI")),
        _ => (0x0000_0633, 0, 0, 0x0080_F9FF),
    };
    cpu.regs[0] = eax;
    cpu.regs[3] = ebx;
    cpu.regs[1] = ecx;
    cpu.regs[2] = edx;
}

/// `rdtsc`: the number of instructions executed, which is the machine's
/// time. `ahead` is how many instructions have run since the count was
/// last brought up to date (none, in the interpreter).
pub fn rdtsc(cpu: &mut Cpu, ahead: u64) {
    let ticks = cpu.instructions + ahead;
    cpu.regs[0] = ticks as u32;
    cpu.regs[2] = (ticks >> 32) as u32;
}

/// Reads a number from memory in one of the formats the x87 unit loads.
pub fn fload(memory: &mut Memory, address: u32, format: FMem) -> Option<f64> {
    Some(match format {
        FMem::F32 => f32::from_bits(memory.read(address, 4)?) as f64,
        FMem::F64 => f64::from_bits(memory.read_u64(address)?),
        FMem::F80 => {
            let mantissa = memory.read_u64(address)?;
            let sign_exponent = memory.read(address.wrapping_add(8), 2)? as u16;
            fpu::f80_to_f64(mantissa, sign_exponent)
        }
        FMem::I16 => memory.read(address, 2)? as i16 as f64,
        FMem::I32 => memory.read(address, 4)? as i32 as f64,
        FMem::I64 => memory.read_u64(address)? as i64 as f64,
    })
}

/// Writes a number to memory in one of the formats the x87 unit stores,
/// rounded as the unit's control word says.
pub fn fstore(cpu: &Cpu, memory: &mut Memory, address: u32, format: FMem, value: f64) -> Option<()> {
    let control = cpu.fpu.control;
    match format {
        FMem::F32 => memory.write(address, 4, fpu::to_f32(value, cpu.fpu.rounding()).to_bits()),
        FMem::F64 => memory.write_u64(address, value.to_bits()),
        FMem::F80 => {
            let (mantissa, sign_exponent) = fpu::f64_to_f80(value);
            memory.write_u64(address, mantissa)?;
            memory.write(address.wrapping_add(8), 2, sign_exponent as u32)
        }
        FMem::I16 => memory.write(address, 2, fpu::to_integer(value, control, 16) as u32),
        FMem::I32 => memory.write(address, 4, fpu::to_integer(value, control, 32) as u32),
        FMem::I64 => memory.write_u64(address, fpu::to_integer(value, control, 64)),
    }
}

/// What a block of generated code answers when an instruction of it
/// faults: the instruction's address goes to `eip` and the instructions
/// run before it are counted, as the interpreter leaves them.
#[cold]
#[inline(never)]
pub fn fault(cpu: &mut Cpu, ran: u32, eip: u32, fault: Fault) -> Result<(), Fault> {
    cpu.eip = eip;
    cpu.instructions += ran as u64;
    Err(fault)
}
